  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import { makePage, type OrgId, type Page, type ProjectId } from "@/types/common";
import { hasRoleAtLeast, type Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

const LIST_PAGE_SIZE = 100;

/**
 * A `private` project is visible only to org admins and owners, platform
 * staff, the project's lead, and explicit project members. `org` and `public`
 * projects stay visible to anyone who already passes the org scope check.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (actor.orgId !== project.orgId) return false;
