async function assertProjectVisible(
  actor: Actor,
  project: Project,
  entity: string,
  id: string,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

async function assertIssueVisible(actor: Actor, issue: Issue): Promise<void> {
  const project = await projectRepo.findProjectById(issue.orgId, issue.projectId);
  if (project === null) return;
  await assertProjectVisible(actor, project, "Issue", issue.id);
}

async function filterVisibleIssues(
  actor: Actor,
  orgId: OrgId,
  issues: readonly Issue[],
): Promise<Issue[]> {
  const projects = new Map<string, Project | null>();
  const visible: Issue[] = [];

  for (const issue of issues) {
    let project = projects.get(issue.projectId);
    if (project === undefined) {
      project = await projectRepo.findProjectById(orgId, issue.projectId);
      projects.set(issue.projectId, project);
    }
    if (project === null || (await canViewProject(actor, project))) {
      visible.push(issue);
    }
  }

  return visible;
}

async function collectIssues(input: IssueFilterInput): Promise<Issue[]> {
  const items: Issue[] = [];
  let cursor: string | null = null;
  const seen = new Set<string>();

  for (;;) {
    const page = await issueRepo.listIssues({
      ...input,
      limit: LIST_PAGE_SIZE,
      cursor,
    });
    for (const issue of page.items) {
      if (seen.has(issue.id)) continue;
      seen.add(issue.id);
      items.push(issue);
    }
    if (page.nextCursor === null || page.items.length === 0) break;
    if (cursor === page.nextCursor) break;
    cursor = page.nextCursor;
  }

  return items;
}

function pageVisible<T extends { readonly id: string; readonly createdAt: string }>(
  rows: readonly T[],
  limit: number,
  cursor: string | null | undefined,
): Page<T> {
  const capped = Math.max(1, Math.min(limit, LIST_PAGE_SIZE));
  const decoded = cursor ? decodeCursor(cursor) : null;
  const resumed =
    decoded === null
      ? rows
      : rows.filter(
          (row) =>
            row.createdAt < decoded.sortValue ||
            (row.createdAt === decoded.sortValue && row.id < decoded.id),
        );
  const items = resumed.slice(0, capped);
  const last = items.at(-1);
  const nextCursor =
    resumed.length > capped && last ? encodeCursor(last.id, last.createdAt) : null;
  return makePage(items, nextCursor, rows.length);
}

